// SPDX-License-Identifier: MIT
import assert from 'node:assert/strict';
import test from 'node:test';
import { retry } from '../src/retry.mjs';

test('returns the first successful result without another attempt', async () => {
  const seen = [];
  const result = await retry(async (attempt) => {
    seen.push(attempt);
    return 'ready';
  });
  assert.equal(result, 'ready');
  assert.deepEqual(seen, [1]);
});

test('the default permits two failures before a successful third attempt', async () => {
  const seen = [];
  const result = await retry(async (attempt) => {
    seen.push(attempt);
    if (attempt < 3) throw new Error('temporary failure');
    return 'ready';
  });
  assert.equal(result, 'ready');
  assert.deepEqual(seen, [1, 2, 3]);
});

test('throws the last error after exhausting the configured attempts', async () => {
  const seen = [];
  const errors = [new Error('first failure'), new Error('last failure')];
  const operation = async (attempt) => {
    seen.push(attempt);
    throw errors[attempt - 1];
  };

  await assert.rejects(
    () => retry(operation, { attempts: errors.length }),
    (error) => {
      assert.strictEqual(error, errors.at(-1));
      return true;
    },
  );
  assert.deepEqual(seen, [1, 2]);
});

test('rejects zero attempts without calling the operation', async () => {
  let calls = 0;

  await assert.rejects(
    () => retry(() => {
      calls += 1;
    }, { attempts: 0 }),
    { name: 'RangeError', message: 'attempts must be a positive integer' },
  );
  assert.equal(calls, 0);
});
